// Checkout conversion fix: ensure paidEvents increment on successful payment
const { logRevenueEvent } = require('./revenueAutopilot');

module.exports = async function processCheckout(session) {
  // ... existing checkout logic ...
  if (session.paymentSuccess) {
    await logRevenueEvent({ type: 'paid', amount: session.amount });
    // additional conversion tracking
  }
  return { status: 'ok' };
};
